# These aren't code addresses. The unwinder may have picked up stale return addresses.
# Let me look for functions in the .data.rel.ro that might be function pointers or 
# check if there are any matching symbols in the debug file's full symbol table

# Search ALL symbols (including LOCAL) near these addresses
aarch64-linux-gnu-readelf -sW libmonosgen-2.0.so.dbg | awk '{
  addr = strtonum("0x"$2);
  size = strtonum("0x"$3);
  if (addr > 0 && addr <= 0x2f4b20 && (addr + size) > 0x2f4b20) print "0x2f4b20 in:", $0
}'

